import{z as s,x as l,o as E,c as o,q as B,j as n,D as e,d as i,s as A,S as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"主备与故障切换","description":"","frontmatter":{"title":"主备与故障切换","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/primary-backup-failover.md","filePath":"cs/primary-backup-failover.md","lastUpdated":1791413859000}'),p={name:"cs/primary-backup-failover.md"};function c(d,a,h,f,_,m){const r=l("Mermaid");return E(),o("div",null,[a[2]||(a[2]=B('<h1 id="主备与故障切换" tabindex="-1">主备与故障切换 <a class="header-anchor" href="#主备与故障切换" aria-label="Permalink to &quot;主备与故障切换&quot;">​</a></h1><div class="epigraph"><p>同一时刻只有一个主接受写。主挂了要切：切慢则不可用，切错则双主，线性一致在缝里破裂。</p><footer>—— 据 Budhiraja, Marzullo, Schneider and Toueg, The Primary-Backup Approach, 1993；Lynch 教材中初级备份整理</footer></div><p>上一课<a href="/cs/cap-pacelc">CAP</a>说分区时要么拒绝要么分叉。主备是最常见的 CP 形状：少数派（旧主所在分区）必须停写。缺口是<strong>切换协议</strong>：谁宣布新主、旧主如何fencing。本课不写 Paxos 全文。后课链式复制把「备」排成一条流水。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>初级备份：客户端把请求发给主，主执行、把状态或日志送到备，再应答。同步备：应答前备已有；异步备：应答后才赶——后者丢失最后若干写，不是线性一致故障切换。</p><p>故障切换：检测器怀疑主 → 选新主 → 旧主若仍活必须拒写。缺口是脑裂：网络分区里两侧都认为自己是主。没有 fencing，线性化点消失，出现分叉写。</p><p><span class="marginnote">Budhiraja 等把主备与状态机复制对照：主备常传状态增量，状态机传输入日志。后课 RSM 再钉。</span></p><p><span class="marginnote">术语翻译：fencing（围栏）就是给每一任主发一个只增不减的纪元号；旧主发出的请求带着小号，存储层一看号过期直接拒绝——靠号码挡住「僵尸主」，而不是靠它自己自觉退出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选主：固定优先级、或租约、或共识（后课）。Fencing：纪元号、磁盘租约、存储序列号——旧主 I/O 被拒绝。客户端必须带纪元，或通过总是问目录服务「现主是谁」。</p>',10)),(E(),n(t,null,{default:e(()=>[A(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20P%5B%22%E4%B8%BB%22%5D%0A%20%20P%20--%3E%20B%5B%22%E5%A4%87%E5%90%8C%E6%AD%A5%22%5D%0A%20%20P%20--%3E%20C%0A%20%20FD%5B%22%E6%A3%80%E6%B5%8B%E5%99%A8%22%5D%20--%3E%20FO%5B%22%E5%88%87%E6%8D%A2%22%5D%0A%20%20FO%20--%3E%20FENCE%5B%22fencing%20%E6%97%A7%E4%B8%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<p>热备 vs 冷备：热备已 apply 日志，切换 RTO 小；冷备从快照赶。RPO 由同步还是异步决定。</p><p><span class="marginnote">数字实例：RPO/RTO 的量法——异步备落后主 30 秒，切换时最坏丢约 30 秒的尾写（RPO≈30 s）；热备把恢复时间 RTO 压到秒级，冷备从快照追日志可能要分钟到小时。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步主备的提交点：多数备还是全部备。等全部则一备慢就拖主（PACELC 的 L）；等一个则那个备挂时可能丢。自动切换依赖<a href="/cs/failure-detectors">故障检测器</a>与<a href="/cs/leases">租约</a>：误怀疑会造成不必要 failover，正确性仍靠纪元单调。</p><p>分区发生时，「有没有 fencing」把系统引向两条完全不同的岔路：</p>',5)),(E(),n(t,null,{default:e(()=>[A(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NET%5B%22%E7%BD%91%E7%BB%9C%E5%88%86%E5%8C%BA%22%5D%20--%3E%20A%5B%22%E5%88%86%E5%8C%BA%20A%EF%BC%9A%E6%97%A7%E4%B8%BB%E8%BF%98%E6%B4%BB%E7%9D%80%22%5D%0A%20%20NET%20--%3E%20B%5B%22%E5%88%86%E5%8C%BA%20B%EF%BC%9A%E5%A4%9A%E6%95%B0%E6%B4%BE%E9%80%89%E5%87%BA%E6%96%B0%E4%B8%BB%20%E7%BA%AA%E5%85%83%E5%8A%A0%E4%B8%80%22%5D%0A%20%20A%20--%3E%20BAD%5B%22%E6%97%A0%20fencing%EF%BC%9A%E6%97%A7%E4%B8%BB%E7%BB%A7%E7%BB%AD%E6%8E%A5%E5%8F%97%E5%86%99%22%5D%0A%20%20BAD%20--%3E%20SPLIT%5B%22%E5%8F%8C%E4%B8%BB%E5%88%86%E5%8F%89%E5%86%99%20%E7%BA%BF%E6%80%A7%E4%B8%80%E8%87%B4%E7%A0%B4%E8%A3%82%22%5D%0A%20%20A%20--%3E%20FENCE%5B%22%E6%97%A7%E4%B8%BB%E5%86%99%E8%AF%B7%E6%B1%82%E5%B8%A6%E6%97%A7%E7%BA%AA%E5%85%83%20%E8%A2%AB%E5%AD%98%E5%82%A8%E5%B1%82%E6%8B%92%E7%BB%9D%22%5D%0A%20%20B%20--%3E%20GOOD%5B%22%E6%96%B0%E4%B8%BB%E4%BB%A5%E6%96%B0%E7%BA%AA%E5%85%83%E6%8E%A5%E5%8F%97%E5%86%99%22%5D%0A%20%20FENCE%20--%3E%20OK%5B%22%E5%90%8C%E6%9C%9F%E8%87%B3%E5%A4%9A%E4%B8%80%E4%B8%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<p><span class="marginnote">为什么重要：切错方向（把活的旧主留着不管）不会立刻报警——两条分叉各自正常服务，直到有人发现同一键读出两个值，那时数据已经坏了，修复要人工对账。</span></p><p>只读从库：默认不是线性一致读。要线性一致读必须读主，或读从库但等到主的提交位置（read index）。这把「有备」和「强读」拆开。</p><p>本课不把 DNS 改 A 记录当 fencing：TTL 期间客户端仍打旧主。也不把云厂商「自动 HA」当协议证明。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写链式复制的头尾，不写 quorum 的 \\(R+W\\)。不引入拜占庭主。后课默认：主备的安全 = 同期至多一主 + 同步复制的提交点；活性 = 检测与选主。脑裂是 fencing 没做，不是 CAP 的新例外。</p><p>切换是分布式系统里最贵的控制面路径之一。正确性在纪元，不在心跳间隔。</p><p><span class="marginnote">常见误区：以为把 DNS 改指新主就算完成切换。TTL 缓存期间客户端仍连旧主、旧主照收写——这不是 fencing，只是把脑裂推迟几分钟再爆发。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同步主备可线性一致；异步备切换会丢尾写。</li><li>故障切换必须 fencing 旧主，防双主。</li><li>从库读默认弱于主上线性一致读。</li><li>出处：Budhiraja et al., 1993；Gray–Cheriton 租约。</li></ul>',9))])}const T=s(p,[["render",c]]);export{D as __pageData,T as default};
